package http

import (
	"html/template"
	"io/fs"
	"log"
	"net/http"
	"os"
	"path/filepath"

	"github.com/gin-gonic/gin"
)

// RegisterFrontendRoutes serves source templates locally and in the Docker image.
// Static hosts use the equivalent HTML generated by scripts/build_frontend.py.
func RegisterFrontendRoutes(router *gin.Engine) bool {
	var root string
	for _, candidate := range []string{"frontend", "../frontend", "../../frontend"} {
		if info, err := os.Stat(filepath.Join(candidate, "templates", "index.html")); err == nil && !info.IsDir() {
			root = candidate
			break
		}
	}
	if root == "" {
		return false
	}
	files := os.DirFS(filepath.Join(root, "templates"))
	var names []string
	if err := fs.WalkDir(files, ".", func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !entry.IsDir() && filepath.Ext(path) == ".html" {
			names = append(names, path)
		}
		return nil
	}); err != nil {
		log.Fatalf("Could not read frontend templates: %v", err)
	}
	pages := template.New("arena")
	for _, name := range names {
		content, err := fs.ReadFile(files, name)
		if err != nil {
			log.Fatalf("Could not read frontend template %s: %v", name, err)
		}
		if _, err := pages.New(name).Parse(string(content)); err != nil {
			log.Fatalf("Could not parse frontend template %s: %v", name, err)
		}
	}
	router.GET("/", func(c *gin.Context) {
		c.Header("Cache-Control", "no-cache")
		c.Header("Content-Type", "text/html; charset=utf-8")
		if err := pages.ExecuteTemplate(c.Writer, "index.html", nil); err != nil {
			log.Printf("Could not render frontend: %v", err)
		}
	})
	router.GET("/sw.js", func(c *gin.Context) {
		c.Header("Content-Type", "application/javascript")
		c.Header("Cache-Control", "no-cache")
		c.File(filepath.Join(root, "sw.js"))
	})
	router.GET("/offline-assets.json", func(c *gin.Context) {
		c.Header("Content-Type", "application/json")
		manifestPath := filepath.Join(root, "offline-assets.json")
		if _, err := os.Stat(manifestPath); err == nil {
			c.File(manifestPath)
			return
		}
		c.JSON(200, []string{
			"/",
			"/static/css/arena.css",
			"/static/js/app.js",
			"/static/js/core/offline-validator.js",
			"/static/js/core/offline-submissions.js",
		})
	})
	router.StaticFS("/static", http.FS(os.DirFS(filepath.Join(root, "static"))))
	router.StaticFS("/assets", http.FS(os.DirFS(filepath.Join(root, "assets"))))
	return true
}
